/* 保养规则：无DOM，时区以工厂日期计算。 */
(function(r){
const need=(v,message,code='VALIDATION')=>{if(!v)throw Object.assign(new Error(message),{code});};
const date=value=>{need(/^\d{4}-\d{2}-\d{2}$/.test(value||''),'日期格式无效');const d=new Date(value+'T00:00:00Z');need(Number.isFinite(+d)&&d.toISOString().slice(0,10)===value,'日期无效');return d;};
const iso=d=>d.toISOString().slice(0,10),add=(d,n)=>new Date(+d+n*86400000);
function actions(p,ctx){const edit=['engineer','supervisor'].includes(ctx.role),review=['supervisor','manager'].includes(ctx.role)&&p.submittedBy!==ctx.person,active=p.activeStatus||(p.activeVersion?'published':null);return {edit:edit&&p.status==='draft',submit:edit&&p.status==='draft',approve:review&&p.status==='pending_review',reject:review&&p.status==='pending_review',pause:edit&&active==='published'&&p.status!=='terminated',resume:edit&&active==='paused',terminate:edit&&['published','paused'].includes(active)&&p.status!=='terminated',revise:edit&&p.status==='published',preview:active==='published'&&['published','draft','pending_review'].includes(p.status)};}

function validate(p,c){need(p.name?.trim()&&p.name.length<=200,'计划名称必填且不超过200字');need(c.equipment.some(e=>e.id===p.equipmentId),'设备不存在');need(p.organization?.trim(),'责任组织必填');date(p.anchorDate);date(p.assignmentValidFrom);if(p.assignmentValidTo)need(date(p.assignmentValidTo)>=date(p.assignmentValidFrom),'人员范围有效期顺序无效');need(['day','week','month'].includes(p.unit),'仅支持时间型日/周/月周期');need(Number.isInteger(p.interval)&&p.interval>0&&p.interval<=365,'间隔须为1至365整数');need(p.timezone==='Asia/Shanghai','工厂时区无效');need([p.windowBefore,p.windowAfter].every(v=>Number.isInteger(v)&&v>=0),'窗口天数须为非负整数');need(p.windowBefore+p.windowAfter<(p.unit==='day'?p.interval:p.unit==='week'?7*p.interval:28*p.interval),'窗口不能重叠');need(Array.isArray(p.bindings)&&p.bindings.length,'至少绑定一个人员或岗位');const people=new Set();for(const b of p.bindings){if(b.type==='person'){need(c.people.some(x=>x.id===b.id),'人员不在维护候选范围');people.add(b.id);}else{const pos=c.positions.find(x=>x.id===b.id);need(b.type==='position'&&pos?.members.length,'岗位不存在或无人');pos.members.forEach(id=>people.add(id));}}need(['assigned','dispatch'].includes(p.assignmentMode),'主责策略无效');need(p.assignmentMode!=='assigned'||people.has(p.primaryPersonId),'指定主责必须在有效人员范围内');need(Array.isArray(p.items)&&p.items.length,'至少维护一个保养项目');for(const item of p.items){need(item.name?.trim()&&item.method?.trim()&&item.criterion?.trim(),'项目名称、方法和标准必填');need(['conclusion','number'].includes(item.resultType),'项目结果类型无效');if(item.resultType==='number')need(item.unit?.trim()&&Number.isFinite(Number(item.min))&&Number.isFinite(Number(item.max))&&item.min!==''&&item.max!==''&&Number(item.min)<=Number(item.max),'数值项目需单位和有效上下限');}return p;}
function occurrence(p,anchor,n){let d;if(p.unit==='month'){const month=anchor.getUTCMonth()+n*p.interval,y=anchor.getUTCFullYear()+Math.floor(month/12),m=month%12,day=Math.min(anchor.getUTCDate(),new Date(Date.UTC(y,m+1,0)).getUTCDate());d=new Date(Date.UTC(y,m,day));}else d=add(anchor,n*p.interval*(p.unit==='week'?7:1));return d;}
function nextWindow(p,from){if(p.status!=='published')return '—';const anchor=date(p.anchorDate),start=date(from);for(let n=0;n<10000;n++){const d=occurrence(p,anchor,n);if(d>=start)return iso(d);}return '超出预览范围';}
function preview(p,c,from,to){need(p.status==='published','仅已发布计划可预览');const start=date(from),end=date(to);need(end>=start&&(+end-+start)/86400000<=366,'预览范围需为0至366天');const anchor=date(p.anchorDate),items=[];for(let n=0;n<10000;n++){let d;d=occurrence(p,anchor,n);if(d>end)break;if(d<start)continue;need(items.length<100,'预览窗口超过100条，请缩小范围');const eq=c.equipment.find(e=>e.id===p.equipmentId);items.push({scheduledAt:iso(d),windowStart:iso(add(d,-p.windowBefore)),windowEnd:iso(add(d,p.windowAfter)),windowKey:p.id+':V'+p.planVersion+':'+iso(d),equipmentId:p.equipmentId,reason:eq?.status!=='active'?'设备非在用，跳过':iso(d)<p.assignmentValidFrom||(p.assignmentValidTo&&iso(d)>p.assignmentValidTo)?'人员范围不在有效期，跳过':'可计划，尚未生成任务',planVersion:p.planVersion});}return {items,total:items.length,timezone:p.timezone,generated:false};}
const api={need,actions,validate,preview,nextWindow};if(typeof module==='object'&&module.exports)module.exports=api;else r.EamMaintenanceRules=api;})(typeof window!=='undefined'?window:globalThis);
